    :root{font-family:var(--tica-font-ui);color:#102342;background:#f4f7fb;--navy:#102342;--blue:#2d63c8;--blue-soft:#edf3ff;--line:#dce5f1;--muted:#65748a;--orange:#df8739;--green:#187354;--green-soft:#eaf7f1;--danger:#a53c35;--danger-soft:#fff1ef}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 92% 0,rgba(45,99,200,.07),transparent 28%),#f4f7fb}button,input{font:inherit}.shell{width:min(1080px,calc(100% - 40px));margin:auto}.top{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(220,229,241,.8)}.brand{display:flex;align-items:center;gap:11px;color:var(--navy);font-weight:850;text-decoration:none}.brand-mark{display:grid;place-items:center;width:37px;height:37px;border-radius:11px;background:var(--blue);color:#fff;font-size:14px;letter-spacing:-.04em}.back{color:var(--blue);font-size:14px;font-weight:800;text-decoration:none}.back:hover{text-decoration:underline}.page-head{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;padding:42px 0 24px}.page-head h1{margin:0;font-size:clamp(30px,4vw,44px);letter-spacing:-.035em;line-height:1.08}.page-head p{max-width:620px;margin:10px 0 0;color:var(--muted);line-height:1.55}.state{display:inline-flex;align-items:center;gap:8px;min-height:34px;padding:0 12px;border-radius:999px;background:#e9eef6;color:#53647d;font-size:13px;font-weight:850;white-space:nowrap}.state:before{content:"";width:8px;height:8px;border-radius:50%;background:#8290a3}.state.on{background:var(--green-soft);color:var(--green)}.state.on:before{background:#2a9b73}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:20px;align-items:start;padding-bottom:64px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 14px 40px rgba(18,48,92,.055)}.main-card{padding:28px}.side-card{padding:22px;position:sticky;top:20px}.notice{display:flex;gap:10px;align-items:flex-start;margin:0 0 20px;padding:13px 15px;border-radius:11px;background:var(--green-soft);color:#176a4e;font-size:14px;line-height:1.45}.notice.err{background:var(--danger-soft);color:#91342e}.notice.warn{background:#fff6e9;color:#8a4b14}.section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:22px}.section-head h2{margin:0;font-size:22px;letter-spacing:-.02em}.section-head p{margin:7px 0 0;color:var(--muted);font-size:14px;line-height:1.5}.shield{display:grid;place-items:center;flex:0 0 54px;width:54px;height:54px;border-radius:16px;background:var(--blue-soft);color:var(--blue)}.shield svg{width:27px;height:27px;fill:none;stroke:currentColor;stroke-width:1.8}.benefits{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0}.benefit{display:flex;gap:10px;padding:14px;border:1px solid var(--line);border-radius:12px;background:#fbfcfe}.benefit i{display:grid;place-items:center;flex:0 0 24px;width:24px;height:24px;border-radius:50%;background:var(--green-soft);color:var(--green);font-style:normal;font-weight:900}.benefit b{display:block;font-size:14px}.benefit small{display:block;margin-top:3px;color:var(--muted);line-height:1.4}.form{margin-top:24px;padding-top:22px;border-top:1px solid var(--line)}.field{display:grid;gap:7px;margin:0 0 16px}.field label{font-size:13px;font-weight:800}.field small{color:var(--muted);line-height:1.45}.field input{width:100%;height:50px;border:1px solid #cbd7e7;border-radius:11px;padding:0 14px;color:var(--navy);background:#fff}.field input:focus{outline:3px solid rgba(45,99,200,.16);border-color:var(--blue)}.code-input{font:800 20px/1 ui-monospace,SFMono-Regular,Menlo,monospace!important;letter-spacing:.16em}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.btn{display:inline-flex;min-height:48px;align-items:center;justify-content:center;border:1px solid transparent;border-radius:11px;padding:0 18px;background:var(--blue);color:#fff;font-weight:800;cursor:pointer;text-decoration:none}.btn:hover{background:#2455ad}.btn.secondary{border-color:var(--line);background:#fff;color:var(--navy)}.btn.secondary:hover{border-color:#b9c9de;background:#f8faff}.btn.danger{border-color:#edc5c1;background:#fff;color:var(--danger)}.btn.danger:hover{background:var(--danger-soft)}.btn:focus-visible,.back:focus-visible{outline:3px solid rgba(45,99,200,.2);outline-offset:2px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:0 0 24px}.step{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px;font-weight:800}.step span{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#e9eef6}.step.done,.step.current{color:var(--blue)}.step.done span{background:var(--green-soft);color:var(--green)}.step.current span{background:var(--blue);color:#fff}.setup-grid{display:grid;grid-template-columns:210px minmax(0,1fr);gap:24px;align-items:start}.qr{display:grid;place-items:center;min-height:210px;padding:7px;border:1px solid var(--line);border-radius:14px;background:#fff}.qr svg{width:196px;height:196px}.manual{margin:12px 0 0}.manual summary{cursor:pointer;color:var(--blue);font-size:13px;font-weight:800}.secret{display:block;margin-top:10px;padding:11px;border-radius:9px;background:#f0f4f9;color:var(--navy);font:700 12px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.method-row{display:flex;align-items:center;gap:14px;padding:16px;border:1px solid var(--line);border-radius:13px;background:#fbfcfe}.method-icon{display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;border-radius:12px;background:var(--green-soft);color:var(--green);font-size:20px}.method-row b{display:block}.method-row small{display:block;margin-top:3px;color:var(--muted)}.recovery{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin:18px 0;padding:16px;border:1px solid var(--line);border-radius:13px;background:#f8fafd}.recovery code{padding:8px;border-radius:8px;background:#fff;text-align:center;font-size:14px;font-weight:800;letter-spacing:.08em}.side-card h2{margin:0 0 15px;font-size:16px}.side-list{list-style:none;margin:0;padding:0}.side-list li{display:flex;gap:10px;padding:11px 0;border-top:1px solid var(--line);color:var(--muted);font-size:13px;line-height:1.45}.side-list li:first-child{border-top:0}.side-list i{color:var(--orange);font-style:normal;font-weight:900}.danger-zone{margin-top:24px;padding-top:22px;border-top:1px solid var(--line)}.danger-zone h3{margin:0;font-size:16px}.danger-zone p{margin:6px 0 0;color:var(--muted);font-size:13px;line-height:1.5}@media(max-width:800px){.shell{width:min(100% - 28px,680px)}.top{height:64px}.page-head{padding-top:28px;align-items:flex-start}.layout{grid-template-columns:1fr}.side-card{position:static}.setup-grid{grid-template-columns:1fr}.qr{width:210px}.steps{grid-template-columns:1fr}.benefits{grid-template-columns:1fr}}@media(max-width:480px){.main-card{padding:20px}.page-head{flex-direction:column;gap:14px}.actions,.btn{width:100%}.recovery{grid-template-columns:1fr}}
  </style>
