@if(count($recoveryCodes))
<script>
  document.getElementById('copy-recovery-codes')?.addEventListener('click', async (event) => {
    const codes = document.getElementById('recovery-codes')?.innerText || '';
    if (!codes || !navigator.clipboard) return;
    await navigator.clipboard.writeText(codes);
    event.currentTarget.textContent = 'Copied';
  });
</script>
@endif
